public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    String s = sc.next();
    int len = s.length();
    int[][] dp = new int[101][len + 1];
    for (int i = 0; i <= 100; i++) {
        Arrays.fill(dp[i], Integer.MAX_VALUE);
    }

    int n = sc.nextInt();
    dp[0][0] = 0;

    for (int i = 1; i <= n; i++) {
        int t = sc.nextInt();
        while (t-- > 0) {
            String th = sc.next();
            for (int j = 0; j <= len - th.length(); j++) {
                dp[i][j] = Math.min(dp[i - 1][j], dp[i][j]);
                if (dp[i - 1][j] == Integer.MAX_VALUE) continue;
                if (s.startsWith(th, j))
                    dp[i][j + th.length()] = Math.min(dp[i - 1][j] + 1, dp[i][j + th.length()]);
            }
        }
    }
    System.out.println(dp[n][len] == Integer.MAX_VALUE ? -1 : dp[n][len]);
}

